## My answer to the prompt

You can use the lower-level `Audio::FAudioCapture` API rather than an `AudioCaptureComponent`. One important caveat: `AGameMode` exists only on the server. This is suitable for a standalone game or a listen-server host, but it will **not** capture microphone input on remote clients. For client-side microphone capture, use a client-owned class such as a PlayerController or a subsystem instead.

The following is a basic UE5 pattern; check the headers in your engine version if API names differ.

**`MyGameMode.h`**
```cpp
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCaptureCore.h"
#include "MyGameMode.generated.h"

UCLASS()
class YOURGAME_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:
    TUniquePtr<Audio::FAudioCapture> Capture;
    bool bStreamOpen = false;
    bool bStreamStarted = false;
};
```

**`MyGameMode.cpp`**
```cpp
#include "MyGameMode.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    Capture = MakeUnique<Audio::FAudioCapture>();

    Audio::FAudioCaptureDeviceParams Params;
    Params.DeviceIndex = INDEX_NONE;       // Default input device
    Params.NumInputChannels = 1;
    Params.SampleRate = 48000;

    bStreamOpen = Capture->OpenCaptureStream(
        Params,
        [this](const float* AudioData,
               int32 NumFrames,
               int32 NumChannels,
               int32 SampleRate,
               double StreamTime,
               bool bOverflow)
        {
            // This callback runs on the audio-capture thread.
            // Copy/queue the data if you need to process it on the game thread.
            // Do not directly access UObjects or gameplay state here.
        },
        1024); // Requested frames per callback

    if (!bStreamOpen)
    {
        UE_LOG(LogTemp, Error, TEXT("Could not open audio capture stream."));
        return;
    }

    bStreamStarted = Capture->StartStream();
    if (!bStreamStarted)
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start audio capture stream."));
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (Capture)
    {
        if (bStreamStarted)
        {
            Capture->StopStream();
            bStreamStarted = false;
        }

        if (bStreamOpen)
        {
            Capture->CloseStream();
            bStreamOpen = false;
        }

        Capture.Reset();
    }

    Super::EndPlay(EndPlayReason);
}
```

