将 `k` 从 1-based 转为 0-based。每一位的候选数字按升序排列；如果当前还剩 `i` 个数字，那么每个候选数字对应 `(i-1)!` 个排列。用 `k / (i-1)!` 选择当前数字，再用 `k % (i-1)!` 更新后续排列中的位置。

```cpp
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> fact(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        vector<int> nums;
        for (int i = 1; i <= n; ++i) {
            nums.push_back(i);
        }

        --k;  // 转为 0-based
        string result;

        for (int i = n; i >= 1; --i) {
            int block = fact[i - 1];
            int pos = k / block;
            result += to_string(nums[pos]);
            nums.erase(nums.begin() + pos);
            k %= block;
        }

        return result;
    }
};
```

