    console.log('Link not found');
    await browser.close();
    return;
  }

  // ------------------------------------------------------------------
  // 3️⃣  Wait for the new page to finish loading
  // ------------------------------------------------------------------
  await page.waitForNavigation({ waitUntil: 'networkidle2' });

  // ------------------------------------------------------------------
  // 4️⃣  Grab the *content* of the element that has data-testid="prediction_option"
  // ------------------------------------------------------------------
  const result = await page.evaluate(() => {
    const el = document.querySelector('[data-testid="prediction_option"]');
