## My answer to the user prompt

Use `AVAudioRecorder` for a straightforward file-backed recording. The view model owns the recorder and publishes the current input level; the SwiftUI view displays that level as bars. Add `NSMicrophoneUsageDescription` to your app’s `Info.plist`.

```swift
import AVFoundation
import SwiftUI

@MainActor
final class AudioRecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var level: CGFloat = 0
    @Published private(set) var recordingURL: URL?
    @Published var errorMessage: String?

    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?

    func startRecording() {
        guard !isRecording else { return }

        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard granted else {
                    self.errorMessage = "Microphone access is required to record."
                    return
                }
                self.beginRecording()
            }
        }
    }

    private func beginRecording() {
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try session.setActive(true)

            let url = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                .appendingPathComponent("Recording-\(UUID().uuidString).m4a")

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(url: url, settings: settings)
            newRecorder.isMeteringEnabled = true
            newRecorder.prepareToRecord()

            guard newRecorder.record() else {
                throw NSError(domain: "AudioRecorder", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Could not start recording."])
            }

            recorder = newRecorder
            recordingURL = url
            isRecording = true
            startMetering()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func startMetering() {
        meterTimer?.invalidate()
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.08, repeats: true) { [weak self] _ in
            guard let self, let recorder = self.recorder else { return }
            recorder.updateMeters()
            let db = recorder.averagePower(forChannel: 0)
            self.level = CGFloat(min(1, max(0, (db + 60) / 60)))
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        recorder?.stop()
        recorder = nil
        meterTimer?.invalidate()
        meterTimer = nil
        isRecording = false
        level = 0

        try? AVAudioSession.sharedInstance().setActive(
            false, options: .notifyOthersOnDeactivation
        )
    }

    deinit {
        meterTimer?.invalidate()
    }
}

struct VoiceRecorderView: View {
    @StateObject private var model = AudioRecorderViewModel()

    private let barFactors: [CGFloat] = [0.45, 0.75, 1.0, 0.65, 0.85, 0.55, 0.9]

    var body: some View {
        VStack(spacing: 36) {
            Text("Voice Recorder")
                .font(.title)

            HStack(alignment: .center, spacing: 7) {
                ForEach(Array(barFactors.enumerated()), id: \.offset) { _, factor in
                    RoundedRectangle(cornerRadius: 4)
                        .fill(model.isRecording ? .red : .gray)
                        .frame(width: 9, height: max(6, 90 * model.level * factor))
                        .animation(.easeInOut(duration: 0.12), value: model.level)
                }
            }
            .frame(height: 100)

            HStack(spacing: 16) {
                Button("Start") { model.startRecording() }
                    .disabled(model.isRecording)

                Button("Stop") { model.stopRecording() }
                    .disabled(!model.isRecording)
            }
            .buttonStyle(.borderedProminent)

            if let url = model.recordingURL, !model.isRecording {
                Text("Saved: \(url.lastPathComponent)")
                    .font(.caption)
                    .lineLimit(1)
            }

            if let error = model.errorMessage {
                Text(error).foregroundStyle(.red)
            }
        }
        .padding()
        .onDisappear { model.stopRecording() }
    }
