### 1. AudioRecorderViewModel

```swift
import Foundation
import AVFoundation

@MainActor
class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var recordingURL: URL?
    @Published var stopRequested = false

    private let audioFileURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!.appendingPathComponent("voice-recording.mp3")

    init() {}

    func startRecording() {
        guard !isRecording && !stopRequested else { return }
        isRecording = true
        stopRequested = false

        // Set up audio session for recording
        let session = AVAudioSession.sharedInstance()
        session.setInputMode(.record, options: [.allowLiveStreaming])

        // Create audio engine
        let engine = try! AVAudioEngine()
        engine.inputSourceType = .microphone
        engine.outputSourceType = .speakers

        // Start continuous recording
        engine.startListening(with: session, mode: .continuous, inputType: .microphone)

        // Give a small delay for initial buffering
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            if self?.isRecording {
                // After a couple of seconds we expect some data
                DispatchQueue.main.asyncAfter(deadline: .now() + 10) { [weak self] in
                    self?.stopRecording()
                }
            }
        }
    }

    func stopRecording() {
        isRecording = false
        stopRequested = true

        // Stop listening
        engine.stopListening()
        engine.pause()

        // Terminate session
        session.stopRunning()
        engine.shutdown()

        // Verify by playing back a short clip (optional)
        // You can use AVAudioPlayer to play the latest chunk.

        // Save the audio file
        do {
            let data = try Data(contentsOf: recordingURL ?? audioFileURL)
            let fileURL = audioFileURL.withExtension(".mp3")
            try data.write(to: fileURL)
            recordingURL = fileURL
        } catch {
            print("Error saving audio file:", error)
        }
    }
}
```

